def main():
    # These URLs describe another component or a fabrication service, not a seller
    # of the specified standard fastener. Do not present them as purchase links.
    for a in items:
        if a['id'] in {'A10','A11','B03','B04','C03','D05','E02','E03'}:
            a['source_url']=None
        if a['group']=='Корпус и ящики':
            a['group']='Корпус'
    spec=dict(date='2026-11-03',geometry_base='cambusa-v08',scope='Предварительная спецификация для расчёта и проверки совместимости, не разрешение на полный заказ.',supplier_contacted=False,ordered=False,rows=items)
    (OUT/'parts.json').write_text(json.dumps(spec,ensure_ascii=False,indent=2)+'\n')
    raw=list(csv.DictReader((ROOT/'outputs/cambusa-proportions-v08/plywood-concept-blanks.csv').open()))
    parts=[]
    for a in raw:
        x={**a,'thickness_mm':float(a['thickness_mm']),'blank_w_mm':float(a['blank_w_mm']),'blank_h_mm':float(a['blank_h_mm']),'quantity':int(a['quantity']),'change_from_v08':None}
        if x['id'] in ['B00-bottom','B01-top']:x['blank_h_mm']=468.;x['change_from_v08']='Предложено сократить глубину на 12 мм под накладной задник.'
        elif x['id'] in ['B02-left-side','B03-right-pegboard']:x['blank_w_mm']=468.;x['change_from_v08']='Предложено сократить глубину на 12 мм под накладной задник; отверстия задней колонки проверить.'
        elif x['id']=='B04-back':x.update(blank_w_mm=1000.,blank_h_mm=1000.,change_from_v08='Предложен накладной задник: можно прикрутить снаружи в торцы корпуса, сохраняя общую глубину 500 мм.')
        elif x['id'] in ['D0-bottom','D1-bottom']:x.update(blank_w_mm=437.,blank_h_mm=322.,change_from_v08='Размер при пазах глубиной 3 мм: (431+6) × (340-24+6). Дно в пазах, ниже дна оставить 13 мм до нижней кромки стенок; уточнить детали под Blum.')
        x['status']='ПРЕДЛОЖЕНИЕ ДЛЯ РАСЧЁТА; НЕ РЕЗАТЬ ДО ПРИСАДКИ'
        parts.append(x)
    (OUT/'wood-parts-proposal.json').write_text(json.dumps(parts,ensure_ascii=False,indent=2)+'\n')
    summary=collections.defaultdict(lambda:dict(count=0,area_m2=0))
    for p in parts:
        key=str(int(p['thickness_mm']));summary[key]['count']+=p['quantity'];summary[key]['area_m2']+=p['blank_w_mm']*p['blank_h_mm']*p['quantity']/1e6
    for s in summary.values():s['area_m2']=round(s['area_m2'],3)
    (OUT/'material-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
    lines=['# Детали Cambusa — подбор v09','', '**Основа формы — v08: 100 × 180 × 50 см, корпус 100 см на основании 80 см, без колёс.**','', 'Это список кандидатов и проектных количеств для расчёта комплекта. Контуры, присадка, опоры и жёсткость основания ещё не утверждены; список пока нельзя использовать как окончательную корзину полного заказа. Поставщикам ничего не отправлено.','', '## Где заказывать','', '- **Фанера и все отверстия:** [Лекс Мебель, СПб](https://raspil78.ru/prisadka/), Михайловский пер., 7А, лит. В. Запасной вариант — [Звено, СПб](https://zveno-web.ru/frezerovka/frezerovka-fanery/). Выполнение конкретной присадки и отделки ещё не подтверждено.', '- **Профиль и совместимый крепёж:** RSI, производство/отгрузка из Челябинска. Это поставщик с доставкой, не найденный склад в СПб.', '- **Петли и планки в СПб:** Мебель Комплект / ФКМ. **Направляющие в СПб:** ТДМ перечисляет точный комплект; резерв — Furnion из Москвы. Цены и остатки различаются.', '- **Эксцентрики:** Hettich через ТД Сервер / Партнёр. Шток 48037 технически найден у производителя, розничная поставка в СПб отдельно не подтверждена.','', '## Фанера','', '| Толщина | Деталей | Чистая площадь заготовок |','|---|---:|---:|']
    for t in sorted(summary,key=int):s=summary[t];lines.append(f'| {t} мм | {s["count"]} | {s["area_m2"]} м² |')
    lines+=['','Всего 48 деревянных деталей. Площадь дана без отходов, пропилов и ориентации рисунка; это не количество листов. Сорт, фактическую толщину и тёмную матовую отделку согласовать на образце. Предлагаемые изменения заготовок перечислены ниже и в wood-parts-proposal.json.','']
    lines += ['[Размеры деревянных заготовок](ФАНЕРА.md) · [Оговорки по каждой позиции и состав комплектов](ПРИМЕЧАНИЯ.md)', '', 'Количество ниже включает небольшой запас там, где он предусмотрен. Точные потребность и запас разделены в примечаниях. Ссылки на технические документы подтверждают характеристики; они не означают найденную розничную поставку.', '']
    for group in dict.fromkeys(a['group'] for a in items):
        lines+=['## '+group,'','| Позиция | Артикул / размер | Предварительная закупка | Цена на странице |','|---|---|---:|---:|']
        for a in (r for r in items if r['group']==group):
            name=f'[{a["name"]}]({a["source_url"]})' if a['source_url'] else a['name']
            qty='уточнить' if a['planned_purchase'] is None else str(a['planned_purchase'])+' '+a['unit']
            price='не подтверждена' if a['published_unit_price_rub'] is None else f'{a["published_unit_price_rub"]:.2f} ₽/{a["unit"]}'
            lines.append(f'| {a["id"]} · {name} | {a["sku"]} | {qty} | {price} |')
        lines.append('')
    lines+=['','## Что изменяется относительно эскиза','', '1. **Днища ящиков:** в модели они были условными накладными. Под выбранный TANDEM предлагаются дно 9 мм в пазах и утопление 13 мм (в диапазоне 12–15 из документации). Предварительный размер каждого дна 437 × 322 мм при пазах по 3 мм. Это наша расчётная геометрия, не универсальный размер Blum. Нужны задние вырезы и отверстия под зацепы по монтажному листу.', '2. **Задник:** предлагается сделать его накладным 1000 × 1000 × 12 мм, сократив глубину верхней/нижней панелей и боковин на 12 мм. Внешние 500 мм сохраняются; задник устанавливается последним снаружи. Старый задник между стенками нельзя просто прикрутить в воздух.', '3. **Опоры:** D30M8H50 заменяют условные подпятники 4 мм. Установочная высота пока не подтверждена. Длина стойки должна быть **770 мм минус установленная высота опоры**; 766 мм из v08 не передавать в резку автоматически.', '4. **Уголки основания:** предложено 18 шт с крышками и совместимыми винтами. Это не проверка жёсткости основания. Раскладка трёхсторонних узлов и доступ ключа должны быть подтверждены в CAD и на одном углу.', '5. **Лотки:** 6 малых уголков на каждый лоток — только схема для пробного образца. Их внешний вид и удержание в фанере 9 мм ещё не проверены. Окончательные отверстия лотков не выпущены.', '6. **Двери:** план 4 петли на дверцу. Масса с лотками, наложение, реальная траектория и положение отверстий относительно перфорации требуют расчёта. Тормоза и колёса в этот комплект не входят.','', '## Цены: что можно считать','', 'Только три крупные позиции: 7,164 м профиля × 1130 + 8 петель × 1130,35 + 2 комплекта направляющих с замками × 4546,82 = **26 231,76 ₽**. Это частичная сумма, не цена всего шкафа: без фанеры, отделки, обработки, планок, остального крепежа и доставки. При оплате трёх целых хлыстов 3020 мм стоимость профиля считается по 9,06 м; выше использована чистая длина из эскиза. Все опубликованные цены — ориентир на дату поиска, без резервирования склада.','', '## Проверенные технические источники','', '- [Blum TANDEM, заказ и проектирование, страницы 20–22](https://d2.blum.com/services/BEC003/me16460573_ep_dok_bau_%24sru_%24aof_%24v4.pdf): 560H3500B, замки T51.1700.04, толщина стенок 11–16, ширина SKW = LW − 42, длина SKL = NL − 10.', '- [Blum 155° с нулевым вхождением](https://d2.blum.com/services/BEC003/clp0034-fl-335_fl_dok_bau_%24sru_%24aof_%24v2.pdf): семейство и артикул 71B7550.', '- [Hettich — присадка Rastex для толщин 12 и 18 мм](https://catalog.hettich.com/General/TuI/ru_RU/catalogs/TuI_ru_RU/pdf/save/bk_1265.pdf).', '- [Чертёж RSI 1037](https://www.rsi-llc.ru/catalog/corner/1037.PDF) и комплекты 5006 + M6×12 на странице товара.','', '## Следующий выпуск','', 'Чтобы выпустить полный заказ: сверить чертёж опоры, спроектировать и проверить один угол основания, присадить петли с лотками и все камовые соединения, сделать контрольный ящик и лоток, затем назначить нагрузку и способ обеспечения устойчивости. До этого можно запрашивать цены и заказывать отдельные контрольные комплектующие.']
    (OUT/'ДЕТАЛИ.md').write_text('\n'.join(lines)+'\n')
    notes=['# Проверки и состав каждой позиции', '', 'Это пояснения к предварительному подбору v09, а не подтверждение готовности к заказу.', '']
    for a in items:
        notes += ['## '+a['id']+' · '+a['name'], '', '**'+a['sku']+'**. Статус: '+a['status']+'.', '', 'Проектная потребность: '+str(a['planned_need'] if a['planned_need'] is not None else 'уточнить')+' '+a['unit']+'; закупка с запасом: '+str(a['planned_purchase'] if a['planned_purchase'] is not None else 'уточнить')+' '+a['unit']+'.', '', a['note'], '']
    (OUT/'ПРИМЕЧАНИЯ.md').write_text('\n'.join(notes)+'\n')
    names={'B00-bottom':'Нижняя панель','B01-top':'Верхняя панель','B02-left-side':'Левая боковина','B03-right-pegboard':'Правая боковина с перфорацией','B04-back':'Накладной задник','B05-divider':'Центральная перегородка'}
    wood=['# Деревянные заготовки v09', '', '**48 отдельных деталей; предварительные размеры для расчёта. Не карта раскроя и не файлы изготовления.**', '', 'Все размеры в миллиметрах. Чистовые размеры и зазоры уточняются с присадкой под реальные петли, стяжки и направляющие. Тёмная отделка и отверстия выполняются до доставки; дома — соединение подготовленных деталей.', '', '| Код | Деталь | Заготовка | Толщина | Количество |', '|---|---|---:|---:|---:|']
    for p in parts:
        ident=p['id'];name=names.get(ident)
        if name is None:
            if 'shelf' in ident:name='Полка'
            elif 'door' in ident:name='Дверца'
            elif 'tray' in p['group'] or ident.startswith('T'):
                name='Лоток: '+('дно' if 'bottom' in ident else 'передний борт' if 'lip' in ident or 'front' in ident else 'боковая стенка')
            elif ident.startswith('D'):
                name='Ящик: '+('дно' if 'bottom' in ident else 'внутренний фасад' if 'face' in ident else 'передняя стенка' if 'front' in ident else 'задняя стенка' if 'back' in ident or 'rear' in ident else 'боковая стенка')
            else:name=p['group']
        wood.append(f'| {ident} | {name} | {p["blank_w_mm"]:g} × {p["blank_h_mm"]:g} | {p["thickness_mm"]:g} | {p["quantity"]} |')
    wood += ['', '## Предлагаемые изменения после v08', '']
    for p in parts:
        if p['change_from_v08']:wood.append('- **'+p['id']+'**: '+p['change_from_v08'])
    wood += ['', 'Модель v08 сохранена как утверждённая форма; перечисленные изменения ещё не внесены в новую модель с крепежом. Направление волокон, кромки, пазы, отверстия и раскрой на листы здесь не заданы.']
    (OUT/'ФАНЕРА.md').write_text('\n'.join(wood)+'\n')
    print(json.dumps({'hardware_rows':len(items),'wood_parts':len(parts),'materials':summary,'known_three_item_subtotal_rub':round(7.164*1130+8*1130.35+2*4546.82,2)},ensure_ascii=False))

